package com.collabspace.websocket; import com.collabspace.entity.PresenceStatus; import com.collabspace.repository.UserRepository; import lombok.RequiredArgsConstructor; import lombok.extern.slf4j.Slf4j; import org.springframework.context.event.EventListener; import org.springframework.data.redis.core.StringRedisTemplate; import org.springframework.messaging.simp.stomp.StompHeaderAccessor; import org.springframework.stereotype.Component; import org.springframework.web.socket.messaging.*; import java.time.Instant; @Component @RequiredArgsConstructor @Slf4j public class WebSocketEventListener {private final UserRepository users;private final StringRedisTemplate redis; @EventListener public void connect(SessionConnectEvent e){StompHeaderAccessor a=StompHeaderAccessor.wrap(e.getMessage());if(a.getUser()!=null){users.findByEmail(a.getUser().getName()).ifPresent(u->{u.setStatus(PresenceStatus.ONLINE);users.save(u);redis.opsForValue().set("user:"+u.getId()+":presence","ONLINE");});}} @EventListener public void disconnect(SessionDisconnectEvent e){StompHeaderAccessor a=StompHeaderAccessor.wrap(e.getMessage());if(a.getUser()!=null){users.findByEmail(a.getUser().getName()).ifPresent(u->{u.setStatus(PresenceStatus.OFFLINE);u.setLastSeen(Instant.now());users.save(u);redis.opsForValue().set("user:"+u.getId()+":presence","OFFLINE");});}}}